mapper.select:
SELECT *
FROM  stock_kline
WHERE 1=1

	AND
	code=#{code}


	AND  date>=#{startDate} 


	AND  date<=#{endDate} 


	AND frequency=#{frequency}

ORDER BY date DESC

	LIMIT #{rows}

SELECT a.*
FROM  stock_kline a
LEFT JOIN stock_info b ON a.code=b.code
WHERE ifnull(v_ma5,0)=0

	AND  a.date>=#{startDate} 


	AND  a.date<=#{endDate} 


	AND b.type=#{type}

ORDER BY a.date DESC

SELECT a.code, a.code_name codeName, a.ipo_date ipoDate, a.out_date out_date, a.type, a.stock_status stockStatus FROM stock_info a WHERE 1 = 1
AND a.type = #{type}
AND (code like '%${key}%' OR code_name like '%${key}%')
